mapper.select:
/* NoticeMapper.selectNoticeList - 공지사항 목록조회 */ SELECT p.pst_id AS pstId, p.bbs_id AS bbsId, p.ttl AS ttl, p.pst_cn AS pstCn, COALESCE(p.ntc_yn,'N') AS ntcYn, COALESCE(p.top_std_yn,'N') AS topStdYn, COALESCE(p.view_use_yn,'N') AS viewUseYn, p.bbs_st_ymd AS bbsStYmd, p.bbs_st_tm AS bbsStTm, p.bbs_ed_ymd AS bbsEdYmd, p.bbs_ed_tm AS bbsEdTm, to_CHAR(p.bbs_st_ymd::DATE,'YYYY-MM-DD')|| ' '|| TO_CHAR(TO_TIMESTAMP(p.bbs_st_tm, 'HH24MISS'), 'HH24:MI') AS bbsStDt, to_CHAR(p.bbs_ed_ymd::DATE,'YYYY-MM-DD')|| ' '|| TO_CHAR(TO_TIMESTAMP(p.bbs_ed_tm, 'HH24MISS'), 'HH24:MI') AS bbsEdDt, p.inq_cnt AS inqCnt, p.rgtr_id AS regId, u.usr_nm AS regNm, TO_CHAR(p.reg_dt, 'YYYY-MM-DD') AS regDt FROM cdm_own.cmpt_bbs_pst p LEFT JOIN cdm_own.usr u ON p.rgtr_id = u.usr_id WHERE p.bbs_id = COALESCE(#{bbsId}, 'NOTICE')
AND p.ttl LIKE '%' || #{ttl} || '%'
AND p.view_use_yn = #{viewUseYn}
AND p.bbs_st_ymd >= #{bbsStYmd}
AND p.bbs_ed_ymd <= #{bbsEdYmd}
ORDER BY CASE WHEN p.top_std_yn = 'Y' THEN 0 ELSE 1 END, -- 상단고정 공지사항 우선 p.reg_dt DESC -- 등록일 최신순

/* NoticeMapper.selectNoticeExists - 공지사항 존재 여부 확인 */
SELECT COUNT(*)
FROM cdm_own.cmpt_bbs_pst
WHERE bbs_id = 'NOTICE'
AND pst_id = #{pstId}

mapper.delete:
/* NoticeMapper.deleteNotice - 공지사항 삭제 */
DELETE FROM cdm_own.cmpt_bbs_pst
WHERE bbs_id = 'NOTICE'
AND pst_id = #{pstId}

mapper.update:
/* NoticeMapper.updateInquiryCount - 공지사항 조회수 증가 */
UPDATE cdm_own.cmpt_bbs_pst
SET inq_cnt = COALESCE(inq_cnt, 0) + 1
WHERE bbs_id = 'NOTICE'
AND pst_id = #{pstId}
